"""Heterogeneous copy amplification: is prod_i (1 + t_i z_i) in the cone generated by
    z^E (1+z)^C = prod_{i in E} z_i prod_{i in C} (1 + z_i),   E, C disjoint, |E| <= m ?
Coefficient matching on the Boolean lattice: for every S, sum_{(E,C): E <= S <= E u C} w(E,C) = prod_{i in S} t_i.
Necessary (weighted top-two coefficients): sum_i (1 - 1/t_i) <= m (all t_i >= 1).
Conjecture: also sufficient.  We test random points on and slightly beyond the boundary.
usage: hetero_cone_lp.py n m trials
"""
import itertools
import sys

import numpy as np
from scipy.optimize import linprog

n, m, trials = int(sys.argv[1]), int(sys.argv[2]), int(sys.argv[3])
rng = np.random.default_rng(7)
subsets = [frozenset(s) for k in range(n + 1) for s in itertools.combinations(range(n), k)]
sidx = {s: i for i, s in enumerate(subsets)}
gens = []
for E in subsets:
    if len(E) > m:
        continue
    rest = [i for i in range(n) if i not in E]
    for k in range(len(rest) + 1):
        for C in itertools.combinations(rest, k):
            gens.append((E, frozenset(C)))
A = np.zeros((len(subsets), len(gens)))
for g, (E, C) in enumerate(gens):
    Cl = sorted(C)
    for k in range(len(Cl) + 1):
        for sub in itertools.combinations(Cl, k):
            A[sidx[E | frozenset(sub)], g] = 1.0


def feasible(t):
    b = np.array([np.prod([t[i] for i in S]) if S else 1.0 for S in subsets])
    res = linprog(np.zeros(len(gens)), A_eq=A, b_eq=b, bounds=[(0, None)] * len(gens), method='highs')
    return res.status == 0


bad_on, bad_beyond = 0, 0
for tr in range(trials):
    # random beta_i in [0,1] with sum = m (boundary), t_i = 1/(1 - beta_i)
    while True:
        beta = rng.dirichlet(np.ones(n)) * m
        if beta.max() < 0.999:
            break
    t = 1.0 / (1.0 - beta)
    on = feasible(t * (1 - 1e-9))
    beyond = feasible(1.0 / (1.0 - np.minimum(beta * 1.01, 0.9999)))
    if not on:
        bad_on += 1
        print('  boundary point NOT feasible: beta =', np.round(beta, 4), flush=True)
    if beyond:
        bad_beyond += 1
print(f'n={n} m={m}: {trials} random boundary points; infeasible on boundary: {bad_on}; '
      f'feasible 1% beyond boundary: {bad_beyond}  (#generators {len(gens)})')
